module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd4 + 2 * xs[0] + 3 * 1 + 8'd4 * xs[1] + 3 * xs[2] + 8'd4 * xs[3] + 3 * xs[4] + 8'd4 * xs[5] + 3 * xs[6] + 8'd4 * xs[7] + 3 * xs[8] + 8'd4 * xs[9] + 3 * xs[10] + 8'd4 * xs[11] + 3 * xs[12] + 8'd4 * xs[13] + 3 * xs[14] + 8'd4 * xs[15] + 3 * xs[16] + 8'd4 * xs[17];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule

